### 3. Preferences Service

```typescript
// services/preferencesService.ts

import { apiClient } from './api';
import {
  UserPreferences,
  PreferencesResponse,
  PreferencesError,
  ErrorResponse,
} from '../types/preferences';

export class PreferencesService {
  private readonly endpoint = '/api/user/preferences';

  /**
   * Get user preferences
   * @throws {PreferencesError} If the request fails
   */
  async getPreferences(): Promise<UserPreferences> {
    try {
      const response = await apiClient.request<PreferencesResponse>(
        this.endpoint,
        {
          method: 'GET',
        }
      );

      if (!response.success) {
        const errorResponse = response as unknown as ErrorResponse;
        throw new PreferencesError(
          errorResponse.message,
          500,
          errorResponse.error
        );
      }

      return response.data;
    } catch (error) {
      if (error instanceof PreferencesError) {
        throw error;
      }

      if (error instanceof Error) {
        // Handle different error types
        if (error.message.includes('401')) {
          throw new PreferencesError(
            'Authentication required. Please login again.',
            401,
            'Unauthorized'
          );
        }

        if (error.message.includes('404')) {
          throw new PreferencesError(
            'Preferences not found',
            404,
            'Not Found'
          );
        }

        if (error.message.includes('500')) {
          throw new PreferencesError(
            'Server error. Please try again later.',
            500,
            'Internal Server Error'
          );
        }

        throw new PreferencesError(
          error.message,
          500,
          'Unknown Error'
        );
      }

      throw new PreferencesError(
        'An unexpected error occurred',
        500,
        'Unknown Error'
      );
    }
  }

  /**
   * Check if error is authentication-related
   */
  isAuthError(error: PreferencesError): boolean {
    return error.statusCode === 401;
  }

  /**
   * Check if error is a server error
   */
  isServerError(error: PreferencesError): boolean {
    return error.statusCode >= 500;
  }
}

export const preferencesService = new PreferencesService();
```

