// hooks/usePreferences.ts

import { useState, useEffect, useCallback } from 'react';
import {
  UserPreferences,
  PreferencesError,
} from '../types/preferences';
import { preferencesService } from '../services/preferencesService';

interface UsePreferencesResult {
  preferences: UserPreferences | null;
  loading: boolean;
  error: PreferencesError | null;
  refetch: () => Promise<void>;
}

export function usePreferences(): UsePreferencesResult {
  const [preferences, setPreferences] = useState<UserPreferences | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<PreferencesError | null>(null);

  const fetchPreferences = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const data = await preferencesService.getPreferences();
      setPreferences(data);
    } catch (err) {
      if (err instanceof PreferencesError) {
        setError(err);

        // Handle authentication errors
        if (preferencesService.isAuthError(err)) {
          // Redirect to login or refresh token
          console.error('Authentication error:', err.message);
        }
      } else {
        setError(
          new PreferencesError(
            'An unexpected error occurred',
            500,
            'Unknown Error'
          )
        );
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchPreferences();
  }, [fetchPreferences]);

  return {
    preferences,
    loading,
    error,
    refetch: fetchPreferences,
  };
}
