```python
# tests/test_preferences.py
import unittest
import jwt
from datetime import datetime, timedelta
from app import create_app
from models.user_preferences import db, User, UserPreferences


class PreferencesTestCase(unittest.TestCase):

    def setUp(self):
        self.app = create_app('testing')
        self.client = self.app.test_client()
        self.app_context = self.app.app_context()
        self.app_context.push()
        db.create_all()

        # Create test user
        self.user = User(email='test@example.com', password_hash='hashed')
        db.session.add(self.user)
        db.session.commit()

        # Create test token
        self.token = jwt.encode(
            {'user_id': self.user.id, 'exp': datetime.utcnow() + timedelta(hours=1)},
            self.app.config['SECRET_KEY'],
            algorithm='HS256'
        )

    def tearDown(self):
        db.session.remove()
        db.drop_all()
        self.app_context.pop()

    def test_get_preferences_success(self):
        """Test successful preferences retrieval"""
        response = self.client.get(
            '/api/user/preferences',
            headers={'Authorization': f'Bearer {self.token}'}
        )
        self.assertEqual(response.status_code, 200)
        data = response.get_json()
        self.assertTrue(data['success'])
        self.assertIn('theme', data['data'])
        self.assertIn('language', data['data'])
        self.assertIn('timezone', data['data'])
        self.assertIn('notifications', data['data'])

    def test_get_preferences_no_auth(self):
        """Test preferences retrieval without authentication"""
        response = self.client.get('/api/user/preferences')
        self.assertEqual(response.status_code, 401)

    def test_get_preferences_invalid_token(self):
        """Test preferences retrieval with invalid token"""
        response = self.client.get(
            '/api/user/preferences',
            headers={'Authorization': 'Bearer invalid-token'}
        )
        self.assertEqual(response.status_code, 401)


if __name__ == '__main__':
    unittest.main()
